def transform(grid):
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    objects=[]
    for color in sorted({v for row in grid for v in row if v!=bg}):
        cells=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color]
        r0=min(r for r,c in cells); r1=max(r for r,c in cells)
        c0=min(c for r,c in cells); c1=max(c for r,c in cells)
        h=r1-r0+1; w=c1-c0+1
        crop=[[grid[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
        objects.append((color,h,w,crop))
    for color,h,w,crop in objects:
        inner=[o for o in objects if o is not None and o[1]<h and o[2]<w]
        if inner:
            out=[[crop[r][c] for c in range(w)] for r in range(h)]
            for _,ih,iw,icrop in inner:
                for r in range(ih):
                    for c in range(iw):
                        if icrop[r][c]!=bg: out[r][c]=icrop[r][c]
            return out
    return []

